BEGIN;

CREATE TEMP TABLE editorial_batch_004 (
  id text PRIMARY KEY,
  summary_es text NOT NULL,
  essay_es text NOT NULL,
  summary_en text NOT NULL,
  essay_en text NOT NULL
);

INSERT INTO editorial_batch_004 VALUES
('cmsvvxiwx00vd85sjzkon25wa', $$Abaporu es una pintura de Tarsila do Amaral, fechada en 1928 y relacionada con el muralismo mexicano. Su figura desproporcionada convierte el cuerpo y la escala en una imagen decisiva del modernismo brasileño.$$,
$$## Cuerpo y escala

[[abaporu|Abaporu]] fue pintado por [[tarsila-do-amaral|Tarsila do Amaral]] en 1928. La obra está relacionada con el [[muralismo-mexicano|muralismo mexicano]] y se conserva en el Museo Nacional de Arte de México.

La figura concentra la atención en un cuerpo de proporciones alteradas. Esa elección no funciona como un detalle anecdótico: hace de la escala, la postura y la presencia corporal el centro de la imagen y explica la fuerza con la que la obra se reconoce dentro del arte moderno latinoamericano.$$,
$$Abaporu is a 1928 painting by Tarsila do Amaral associated with Mexican muralism. Its disproportionate figure turns the body and scale into a decisive image within Brazilian modernism.$$,
$$## Body and scale

[[abaporu|Abaporu]] was painted by [[tarsila-do-amaral|Tarsila do Amaral]] in 1928. The work is associated with [[muralismo-mexicano|Mexican muralism]] and is held by the Museo Nacional de Arte in Mexico City.

The figure concentrates attention on a body whose proportions have been altered. This is not an incidental detail: scale, posture, and bodily presence become the image’s central subjects, helping explain the work’s force within Latin American modern art.$$),
('cmsvvxijr00ng85sj1i18suum', $$Casa de la Cascada es una obra de Frank Lloyd Wright, construida en 1935 en Mill Run, Pensilvania. Su arquitectura moderna integra hormigón, piedra, acero y vidrio con la experiencia del paisaje y del espacio habitado.$$,
$$## Arquitectura y paisaje

[[casa-sobre-la-cascada|Casa de la Cascada]] fue diseñada por [[frank-lloyd-wright|Frank Lloyd Wright]] y construida en 1935 en Mill Run, Pensilvania. Está relacionada con la [[arquitectura-moderna|arquitectura moderna]], el hormigón, el acero y el espacio público.

La obra importa por la manera en que convierte los materiales y el emplazamiento en parte de la arquitectura. El hormigón, la piedra, el acero y el vidrio no aparecen como una lista técnica separada del lugar: organizan la relación entre la casa, la roca y el paisaje.$$,
$$Fallingwater is a work by Frank Lloyd Wright, built in 1935 at Mill Run, Pennsylvania. Its modern architecture brings concrete, stone, steel, and glass into the experience of landscape and inhabited space.$$,
$$## Architecture and landscape

[[casa-sobre-la-cascada|Fallingwater]] was designed by [[frank-lloyd-wright|Frank Lloyd Wright]] and built in 1935 at Mill Run, Pennsylvania. It is associated with [[arquitectura-moderna|modern architecture]], concrete, steel, and public space.

The work matters because it makes materials and setting part of the architecture. Concrete, stone, steel, and glass are not a technical list detached from the site: they organize the relationship between the house, the rock, and the landscape.$$),
('cmsvvxikv00o485sjsxt04vp1', $$Cut Piece es una performance de Yoko Ono, fechada en 1964 y relacionada con Fluxus. La obra convierte la participación del público y la vulnerabilidad del cuerpo en el material central de la acción.$$,
$$## Participación y cuerpo

[[cut-piece|Cut Piece]] fue realizada por [[yoko-ono|Yoko Ono]] en 1964 y está relacionada con [[fluxus|Fluxus]]. Su técnica es la performance: la obra sucede mediante una acción y no como un objeto estable separado de quien la presencia.

La participación del público altera la relación entre artista, espectadores y cuerpo. La vulnerabilidad no se presenta sólo como tema; se produce en tiempo real dentro de la situación compartida.$$,
$$Cut Piece is a 1964 performance by Yoko Ono associated with Fluxus. It makes audience participation and the vulnerability of the body the central materials of the action.$$,
$$## Participation and the body

[[cut-piece|Cut Piece]] was performed by [[yoko-ono|Yoko Ono]] in 1964 and is associated with [[fluxus|Fluxus]]. Its medium is performance: the work takes place through an action rather than as a stable object separate from its viewers.

Audience participation changes the relationship between artist, spectators, and body. Vulnerability is not only a subject here; it is produced in real time within the shared situation.$$),
('cmsvvxifq00l485sjeqi3s1tz', $$David es una escultura de Miguel Ángel, tallada en mármol en 1501 y conservada en la Galleria dell’Accademia de Florencia. Relacionada con el Renacimiento italiano, la obra concentra cuerpo, desnudo y tradición clásica en una figura monumental.$$,
$$## Cuerpo y tradición

[[david-de-miguel-angel|David]] fue tallado por [[miguel-angel|Miguel Ángel]] a partir de 1501. Es una escultura de mármol de 517 cm de altura, conservada en la Galleria dell’Accademia de Florencia y relacionada con el [[renacimiento-italiano|Renacimiento italiano]].

La escala transforma el cuerpo en presencia pública. El desnudo y la talla permiten reconocer la continuidad con la tradición clásica, mientras que la dimensión monumental convierte esa tradición en una experiencia física para quien mira.$$,
$$David is a marble sculpture by Michelangelo, carved from 1501 and held by the Galleria dell’Accademia in Florence. Associated with the Italian Renaissance, it brings the body, the nude, and classical tradition together in a monumental figure.$$,
$$## Body and tradition

[[david-de-miguel-angel|David]] was carved by [[miguel-angel|Michelangelo]] from 1501 onward. It is a 517 cm marble sculpture held by the Galleria dell’Accademia in Florence and associated with the [[renacimiento-italiano|Italian Renaissance]].

Its scale turns the body into a public presence. The nude and the carved material show continuity with classical tradition, while the monumental dimension makes that tradition a physical experience for the viewer.$$),
('cmtaf2hmh000h07qtg1hpw0bz', $$El grito es una obra de Edvard Munch, fechada en 1893 y relacionada con el Expresionismo. Realizada con témpera, óleo y pastel sobre cartón, convierte el cuerpo en una imagen de intensidad emocional.$$,
$$## Intensidad y expresión

[[el-grito|El grito]] fue realizado por [[edvard-munch|Edvard Munch]] en 1893. Combina témpera, óleo y pastel sobre cartón, y está relacionado con el [[expresionismo|Expresionismo]] y con el cuerpo.

La obra no presenta el cuerpo como una figura estable o idealizada. Su deformación y la intensidad de la escena hacen visible una experiencia llevada al límite, una de las razones por las que la imagen se ha convertido en un emblema de la expresión moderna.$$,
$$The Scream is a work by Edvard Munch, dated 1893 and associated with Expressionism. Made with tempera, oil, and pastel on cardboard, it turns the body into an image of emotional intensity.$$,
$$## Intensity and expression

[[el-grito|The Scream]] was made by [[edvard-munch|Edvard Munch]] in 1893. It combines tempera, oil, and pastel on cardboard, and is associated with [[expresionismo|Expressionism]] and the body.

The work does not present the body as a stable or idealized figure. Its distortion and the intensity of the scene make an experience at the limit visible, helping explain why the image has become an emblem of modern expression.$$),
('cmsvvxih800m185sj3ztb0h6g', $$La Libertad guiando al pueblo es una pintura de Eugène Delacroix, fechada en 1830 y relacionada con el Romanticismo y la revolución. El óleo sobre lienzo transforma un episodio político en una imagen alegórica de gran fuerza pública.$$,
$$## Revolución y alegoría

[[libertad-guiando-al-pueblo|La Libertad guiando al pueblo]] fue pintada por [[eugene-delacroix|Eugène Delacroix]] en 1830. Es un óleo sobre lienzo relacionado con el [[romanticismo|Romanticismo]] y con la [[revolucion|revolución]].

La obra une un acontecimiento político con una figura alegórica. Esa combinación explica su importancia: la pintura no sólo registra un conflicto, sino que lo convierte en una imagen colectiva de libertad, movimiento y participación pública.$$,
$$Liberty Leading the People is a painting by Eugène Delacroix, dated 1830 and associated with Romanticism and revolution. The oil painting on canvas turns a political event into a powerful public allegory.$$,
$$## Revolution and allegory

[[libertad-guiando-al-pueblo|Liberty Leading the People]] was painted by [[eugene-delacroix|Eugène Delacroix]] in 1830. It is an oil painting on canvas associated with [[romanticismo|Romanticism]] and revolution.

The work brings a political event together with an allegorical figure. That combination explains its importance: the painting does not simply record a conflict, but turns it into a collective image of freedom, movement, and public participation.$$),
('cmsvvxijh00na85sj6s3t1yu1', $$Las dos Fridas es una pintura de Frida Kahlo, fechada en 1939 y relacionada con el autorretrato, la identidad, el cuidado y el género. El óleo sobre lienzo convierte el desdoblamiento del cuerpo en una imagen de vínculos y tensión interior.$$,
$$## Identidad y cuidado

[[las-dos-fridas|Las dos Fridas]] fue pintada por [[frida-kahlo|Frida Kahlo]] en 1939. Es un óleo sobre lienzo de 173,5 × 173 cm, conservado en el Museo de Arte Moderno de Ciudad de México y relacionado con el autorretrato, la identidad, el cuidado y el género.

La duplicación de la figura no funciona como una simple repetición. Hace visible una identidad presentada como relación: dos cuerpos se conectan, se sostienen y exponen una tensión que la pintura mantiene abierta.$$,
$$The Two Fridas is a 1939 painting by Frida Kahlo associated with self-portraiture, identity, care, and gender. The oil painting on canvas turns the doubling of the body into an image of connection and inner tension.$$,
$$## Identity and care

[[las-dos-fridas|The Two Fridas]] was painted by [[frida-kahlo|Frida Kahlo]] in 1939. It is a 173.5 × 173 cm oil painting on canvas held by the Museo de Arte Moderno in Mexico City and associated with self-portraiture, identity, care, and gender.

The doubled figure is not simply a repetition. It makes identity visible as a relationship: two bodies connect, support one another, and expose a tension that the painting leaves open.$$),
('cmtaf2hna000y07qtvaqt07ir', $$Latas de sopa Campbell es una serie de Andy Warhol, fechada en 1962 y relacionada con el Pop Art, la publicidad, el consumo y los medios de masas. La repetición de un producto cotidiano convierte la circulación comercial en materia artística.$$,
$$## Repetición y consumo

[[campbells-soup-cans|Latas de sopa Campbell]] fue realizada por [[andy-warhol|Andy Warhol]] en 1962. Cada lienzo mide 50,8 × 40,6 cm; la serie está relacionada con el [[pop-art|Pop Art]], la publicidad, el consumo y los medios de masas.

La elección de una marca reconocible desplaza la atención desde el objeto aislado hacia su circulación pública. La repetición hace visible cómo una imagen comercial puede convertirse en motivo, signo y superficie del arte.$$,
$$Campbell’s Soup Cans is a 1962 series by Andy Warhol associated with Pop Art, advertising, consumer culture, and mass media. Repeating an everyday product turns commercial circulation into artistic material.$$,
$$## Repetition and consumption

[[campbells-soup-cans|Campbell’s Soup Cans]] was made by [[andy-warhol|Andy Warhol]] in 1962. Each canvas measures 50.8 × 40.6 cm; the series is associated with [[pop-art|Pop Art]], advertising, consumer culture, and mass media.

Choosing a recognizable brand shifts attention from the isolated object to its public circulation. Repetition makes visible how a commercial image can become the subject, sign, and surface of art.$$),
('cmsvvxifd00kx85sjy9ug3izc', $$La última cena es una pintura mural de Leonardo da Vinci, fechada en 1495 y conservada en Santa Maria delle Grazie, Milán. Relacionada con el Renacimiento italiano, la perspectiva y la pintura religiosa, organiza una escena sagrada como problema espacial.$$,
$$## Espacio y relato religioso

[[ultima-cena|La última cena]] fue realizada por [[leonardo-da-vinci|Leonardo da Vinci]] entre 1495 y 1498 en Santa Maria delle Grazie, Milán. Es una técnica mixta mural de 460 × 880 cm, relacionada con el [[renacimiento-italiano|Renacimiento italiano]], la perspectiva y la pintura religiosa.

La escena importa tanto por el episodio representado como por la forma en que distribuye figuras, miradas y arquitectura. La perspectiva convierte el muro en un espacio narrativo y dirige la atención hacia el centro de la composición.$$,
$$The Last Supper is a mural painting by Leonardo da Vinci, begun in 1495 and held at Santa Maria delle Grazie in Milan. Associated with the Italian Renaissance, perspective, and religious painting, it organizes a sacred scene as a spatial problem.$$,
$$## Space and religious narrative

[[ultima-cena|The Last Supper]] was made by [[leonardo-da-vinci|Leonardo da Vinci]] between 1495 and 1498 at Santa Maria delle Grazie in Milan. It is a 460 × 880 cm mixed-media mural associated with the [[renacimiento-italiano|Italian Renaissance]], perspective, and religious painting.

The scene matters both for the episode it represents and for the way it distributes figures, gazes, and architecture. Perspective turns the wall into a narrative space and directs attention toward the center of the composition.$$),
('cmsvvxig900lg85sjdu44btea', $$La vocación de san Mateo es una pintura de Caravaggio, fechada en 1599 y relacionada con el Barroco, la religión y la luz. El óleo sobre lienzo convierte un episodio bíblico en una escena inmediata y dramática.$$,
$$## Luz y conversión

[[vocacion-de-san-mateo|La vocación de san Mateo]] fue pintada por [[caravaggio|Michelangelo Merisi da Caravaggio]] en 1599. Es un óleo sobre lienzo de 322 × 340 cm, conservado en San Luigi dei Francesi de Roma y relacionado con el [[barroco|Barroco]], la religión y la luz.

La iluminación no sólo hace visibles las figuras: organiza el momento de la llamada y concentra la acción. El relato religioso aparece así dentro de un espacio reconocible, con cuerpos y gestos que acercan la escena al presente del espectador.$$,
$$The Calling of Saint Matthew is a 1599 painting by Caravaggio associated with the Baroque, religion, and light. The oil painting on canvas turns a biblical episode into an immediate and dramatic scene.$$,
$$## Light and conversion

[[vocacion-de-san-mateo|The Calling of Saint Matthew]] was painted by [[caravaggio|Michelangelo Merisi da Caravaggio]] in 1599. It is a 322 × 340 cm oil painting on canvas held at San Luigi dei Francesi in Rome and associated with the [[barroco|Baroque]], religion, and light.

Light does more than make the figures visible: it organizes the moment of the call and concentrates the action. The religious narrative therefore unfolds within a recognizable space, with bodies and gestures that bring the scene close to the viewer’s present.$$),
('cmsvvxijc00n785sjn233jnsz', $$La persistencia de la memoria es una pintura de Salvador Dalí, fechada en 1931 y relacionada con el Surrealismo. Sus relojes blandos sitúan el tiempo, la memoria y la percepción en el centro de una escena de pequeño formato.$$,
$$## Tiempo y percepción

[[la-persistencia-de-la-memoria|La persistencia de la memoria]] fue pintada por [[salvador-dali|Salvador Dalí]] en 1931. Es un óleo sobre lienzo de 24,1 × 33 cm, conservado en el Museum of Modern Art de Nueva York y relacionado con el [[surrealismo|Surrealismo]], el tiempo y la memoria.

Los relojes deformados no ilustran el tiempo como una medida estable. Lo convierten en una experiencia extraña y mutable, y hacen que un espacio reducido baste para cuestionar la forma en que organizamos la realidad.$$,
$$The Persistence of Memory is a 1931 painting by Salvador Dalí associated with Surrealism. Its soft watches place time, memory, and perception at the center of a small-scale scene.$$,
$$## Time and perception

[[la-persistencia-de-la-memoria|The Persistence of Memory]] was painted by [[salvador-dali|Salvador Dalí]] in 1931. It is a 24.1 × 33 cm oil painting on canvas held by the Museum of Modern Art in New York and associated with [[surrealismo|Surrealism]], time, and memory.

The distorted watches do not depict time as a stable measure. They turn it into a strange and changeable experience, allowing a small space to question the way we organize reality.$$),
('cmsvvxilj00oj85sjjhqdmo1e', $$Lluvia repentina sobre el puente Ohashi es una xilografía de Utagawa Hiroshige, fechada en 1857 y relacionada con el ukiyo-e, el paisaje y la naturaleza. La imagen convierte un cambio atmosférico en una experiencia visual instantánea.$$,
$$## Paisaje y atmósfera

[[lluvia-repentina-sobre-el-puente-ohashi|Lluvia repentina sobre el puente Ohashi]] fue realizada por [[utagawa-hiroshige|Utagawa Hiroshige]] en 1857. Es una xilografía sobre papel relacionada con el [[ukiyo-e|ukiyo-e]], el paisaje y la naturaleza.

La lluvia reorganiza la escena y modifica la manera de percibir el puente, las figuras y el espacio. El paisaje no aparece como un fondo inmóvil, sino como un acontecimiento que cambia ante los ojos.$$,
$$Sudden Shower over Shin-Ōhashi Bridge is a 1857 woodblock print by Utagawa Hiroshige associated with ukiyo-e, landscape, and nature. The image turns a change in weather into an instantaneous visual experience.$$,
$$## Landscape and atmosphere

[[lluvia-repentina-sobre-el-puente-ohashi|Sudden Shower over Shin-Ōhashi Bridge]] was made by [[utagawa-hiroshige|Utagawa Hiroshige]] in 1857. It is a woodblock print on paper associated with [[ukiyo-e|ukiyo-e]], landscape, and nature.

Rain reorganizes the scene and changes how the bridge, figures, and space are perceived. Landscape is not an immobile background here, but an event that changes before the viewer’s eyes.$$),
('cmsvvxii400mj85sj3635r3yj', $$Los girasoles es una pintura de Vincent van Gogh, fechada en 1888 y relacionada con el Postimpresionismo, el paisaje y la naturaleza. El óleo sobre lienzo convierte un motivo cotidiano en una superficie de color intenso.$$,
$$## Color y naturaleza

[[los-girasoles|Los girasoles]] fue pintado por [[vincent-van-gogh|Vincent van Gogh]] en 1888. Es un óleo sobre lienzo de 92,1 × 73 cm, conservado en la National Gallery de Londres y relacionado con el [[postimpresionismo|Postimpresionismo]], el paisaje y la naturaleza.

El motivo es sencillo, pero la pintura lo vuelve una experiencia de color y materia. Las flores permiten reconocer cómo una forma natural puede sostener una composición completa y cargarla de intensidad visual.$$,
$$Sunflowers is an 1888 painting by Vincent van Gogh associated with Post-Impressionism, landscape, and nature. The oil painting on canvas turns an everyday motif into a surface of intense color.$$,
$$## Color and nature

[[los-girasoles|Sunflowers]] was painted by [[vincent-van-gogh|Vincent van Gogh]] in 1888. It is a 92.1 × 73 cm oil painting on canvas held by the National Gallery in London and associated with [[postimpresionismo|Post-Impressionism]], landscape, and nature.

The subject is simple, but painting turns it into an experience of color and material. The flowers show how a natural form can sustain an entire composition and charge it with visual intensity.$$),
('cmsvvxik100nm85sj8qyrvcxt', $$Madre migrante es una fotografía de Dorothea Lange, fechada en 1936 y relacionada con migración, trabajo, raza, clase social y memoria. La gelatina de plata convierte una situación histórica de precariedad en una imagen duradera.$$,
$$## Fotografía y memoria social

[[migrant-mother|Madre migrante]] fue realizada por [[dorothea-lange|Dorothea Lange]] en 1936. Es una fotografía en gelatina de plata sobre papel, conservada en la Library of Congress de Washington, D. C., y relacionada con migración, trabajo, raza, clase social y memoria.

La importancia de la imagen está en la tensión entre una persona concreta y las condiciones sociales que la rodean. La fotografía conserva una situación de precariedad y, al mismo tiempo, la convierte en una imagen pública de la experiencia migratoria.$$,
$$Migrant Mother is a 1936 photograph by Dorothea Lange associated with migration, labor, race, social class, and memory. The gelatin silver print turns a historical situation of hardship into a lasting image.$$,
$$## Photography and social memory

[[migrant-mother|Migrant Mother]] was made by [[dorothea-lange|Dorothea Lange]] in 1936. It is a gelatin silver photograph on paper held by the Library of Congress in Washington, D.C., and associated with migration, labor, race, social class, and memory.

The image matters because of the tension between a particular person and the social conditions around her. Photography preserves a situation of hardship while also turning it into a public image of migrant experience.$$),
('cmsvvxiet00kl85sjzb74idc4', $$La Mezquita de Córdoba es un monumento de arquitectura islámica iniciado en 785 en Córdoba, España. Sus relaciones con religión, arquitectura y espacio público muestran cómo un edificio puede acumular usos, memoria y transformaciones históricas.$$,
$$## Arquitectura y memoria

La [[gran-mezquita-de-cordoba|Mezquita de Córdoba]] comenzó a construirse en 785 en Córdoba, España. Está relacionada con el [[arte-islamico|arte islámico]], la religión, la arquitectura y el espacio público; sus materiales incluyen piedra, ladrillo y mármol.

El monumento importa porque su forma no puede separarse de la historia de los usos que ha albergado. La arquitectura aparece como una estructura material y, a la vez, como un lugar donde distintas memorias culturales permanecen visibles.$$,
$$The Mosque–Cathedral of Córdoba is a monument of Islamic architecture begun in 785 in Córdoba, Spain. Its relations with religion, architecture, and public space show how a building can accumulate uses, memory, and historical transformations.$$,
$$## Architecture and memory

The [[gran-mezquita-de-cordoba|Mosque–Cathedral of Córdoba]] was begun in 785 in Córdoba, Spain. It is associated with [[arte-islamico|Islamic art]], religion, architecture, and public space; its materials include stone, brick, and marble.

The monument matters because its form cannot be separated from the history of the uses it has housed. Architecture appears as a material structure and also as a place where different cultural memories remain visible.$$),
('cmsvvxii900mm85sj1d207e62', $$Mont Sainte-Victoire es una pintura de Paul Cézanne, fechada en 1904 y relacionada con el Postimpresionismo, el paisaje y la naturaleza. El óleo sobre lienzo convierte una montaña reconocible en un problema de percepción y construcción pictórica.$$,
$$## Paisaje y construcción

[[mont-sainte-victoire|Mont Sainte-Victoire]] fue pintado por [[paul-cezanne|Paul Cézanne]] en 1904. Es un óleo sobre lienzo relacionado con el [[postimpresionismo|Postimpresionismo]], el paisaje y la naturaleza.

La montaña permanece reconocible, pero la pintura no se limita a describirla. La relación entre paisaje, superficie y estructura permite entender cómo una escena natural puede construirse mediante decisiones de forma y color.$$,
$$Mont Sainte-Victoire is a 1904 painting by Paul Cézanne associated with Post-Impressionism, landscape, and nature. The oil painting on canvas turns a recognizable mountain into a problem of perception and pictorial construction.$$,
$$## Landscape and construction

[[mont-sainte-victoire|Mont Sainte-Victoire]] was painted by [[paul-cezanne|Paul Cézanne]] in 1904. It is an oil painting on canvas associated with [[postimpresionismo|Post-Impressionism]], landscape, and nature.

The mountain remains recognizable, but the painting does not simply describe it. The relationship between landscape, surface, and structure shows how a natural scene can be built through decisions of form and color.$$),
('cmsvvxiej00kf85sjzon0uefc', $$El Panteón de Roma es un monumento de arquitectura romana situado en Roma y relacionado con el espacio público y la memoria monumental. Su escala y su larga duración hacen visible cómo la arquitectura organiza una experiencia colectiva.$$,
$$## Monumento y ciudad

El [[panteon-de-roma|Panteón de Roma]] está relacionado con la arquitectura romana, el monumento y el espacio público. El registro lo sitúa en Roma y atribuye su construcción a [[apolodoro-de-damasco|Apollodoro de Damasco]].

Su importancia no depende sólo de la antigüedad del edificio. La permanencia de su forma muestra cómo un espacio arquitectónico puede atravesar épocas, conservar memoria y seguir estructurando la experiencia pública de una ciudad.$$,
$$The Pantheon of Rome is a Roman architectural monument located in Rome and associated with public space and monumental memory. Its scale and long duration show how architecture organizes a collective experience.$$,
$$## Monument and city

The [[panteon-de-roma|Pantheon of Rome]] is associated with Roman architecture, the monument, and public space. The record locates it in Rome and attributes its construction to [[apolodoro-de-damasco|Apollodorus of Damascus]].

Its importance does not depend only on the building’s age. The persistence of its form shows how an architectural space can cross periods, preserve memory, and continue to structure a city’s public experience.$$),
('cmsvvxim200ov85sjpgdw6l3r', $$La Piedra del Sol es una escultura mexica de basalto, fechada en 1479 y conservada en el Museo Nacional de Antropología de Ciudad de México. Relacionada con el imperio y el arte mexica, reúne materia, calendario y poder cultural.$$,
$$## Piedra, tiempo y poder

La [[piedra-del-sol|Piedra del Sol]] es una escultura de basalto fechada en 1479. Está relacionada con el [[arte-mexica|arte mexica]], el imperio y el Museo Nacional de Antropología de Ciudad de México.

La pieza importa porque convierte una superficie pétrea en un sistema de signos vinculado al tiempo y al orden cultural. Su presencia monumental permite leer la escultura como objeto material y como afirmación de una visión del mundo.$$,
$$The Aztec Sun Stone is a basalt sculpture dated 1479 and held by the Museo Nacional de Antropología in Mexico City. Associated with Aztec art, empire, and cultural power, it brings material, calendar, and authority together.$$,
$$## Stone, time, and power

The [[piedra-del-sol|Aztec Sun Stone]] is a basalt sculpture dated 1479. It is associated with [[arte-mexica|Aztec art]], empire, and the Museo Nacional de Antropología in Mexico City.

The work matters because it turns a stone surface into a system of signs connected with time and cultural order. Its monumental presence makes it possible to read sculpture both as material object and as an assertion of a worldview.$$),
('cmsvvxjhf018m85sjh0dcl9rx', $$Psique reanimada por el beso es una escultura de Antonio Canova, iniciada en 1787 y relacionada con el Neoclasicismo y el mito. Tallada en mármol, convierte un instante narrativo en una composición de equilibrio y contacto.$$,
$$## Mito y contacto

[[psique-reanimada-por-el-beso|Psique reanimada por el beso]] fue realizada por [[antonio-canova|Antonio Canova]] a partir de 1787. Es una escultura de mármol relacionada con el [[neoclasicismo|Neoclasicismo]], el mito y la religión.

La obra detiene un momento de la historia de Psique y Cupido en el punto exacto del acercamiento. El mármol hace que ese contacto parezca simultáneamente físico y suspendido, una tensión central para la experiencia de la escultura.$$,
$$Psyche Revived by Cupid’s Kiss is a sculpture by Antonio Canova, begun in 1787 and associated with Neoclassicism and myth. Carved in marble, it turns a narrative instant into a composition of balance and contact.$$,
$$## Myth and contact

[[psique-reanimada-por-el-beso|Psyche Revived by Cupid’s Kiss]] was made by [[antonio-canova|Antonio Canova]] from 1787 onward. It is a marble sculpture associated with [[neoclasicismo|Neoclassicism]], myth, and religion.

The work arrests a moment from the story of Psyche and Cupid at the exact point of their approach. Marble makes the contact seem both physical and suspended, a tension central to the experience of sculpture.$$),
('cmsvvxieo00ki85sjtiomfod6', $$Santa Sofía es un monumento de arquitectura bizantina construido en 532 en Estambul. Relacionada con religión, arquitectura y espacio público, fue atribuida a Antemio de Tralles e Isidoro de Mileto y muestra cómo una obra puede reunir saber técnico y significado colectivo.$$,
$$## Arquitectura y significado colectivo

[[hagia-sophia|Santa Sofía]] fue construida en 532 en Estambul y está relacionada con el [[arte-bizantino|arte bizantino]], la religión, la arquitectura y el espacio público. Su construcción se atribuye a [[antemio-de-tralles|Antemio de Tralles]] e Isidoro de Mileto.

El monumento importa porque la arquitectura funciona aquí como estructura, espacio ceremonial y signo cultural al mismo tiempo. Piedra, ladrillo y mármol sostienen una experiencia en la que la técnica y el significado colectivo no pueden separarse.$$,
$$Hagia Sophia is a Byzantine architectural monument built in 532 in Istanbul. Associated with religion, architecture, and public space, it was attributed to Anthemius of Tralles and Isidore of Miletus and shows how a work can bring technical knowledge and collective meaning together.$$,
$$## Architecture and collective meaning

[[hagia-sophia|Hagia Sophia]] was built in 532 in Istanbul and is associated with [[arte-bizantino|Byzantine art]], religion, architecture, and public space. Its construction is attributed to [[antemio-de-tralles|Anthemius of Tralles]] and Isidore of Miletus.

The monument matters because architecture functions here as structure, ceremonial space, and cultural sign at once. Stone, brick, and marble sustain an experience in which technique and collective meaning cannot be separated.$$);

UPDATE "Entity" e SET summary=b.summary_es, content=b.essay_es FROM editorial_batch_004 b WHERE e.id=b.id;
UPDATE "EntityTranslation" t SET "shortDescription"=b.summary_es, essay=b.essay_es, excerpt=b.summary_es FROM editorial_batch_004 b WHERE t."entityId"=b.id AND t.locale='es';
INSERT INTO "EntityTranslation" (id,"entityId",locale,title,"shortDescription",essay,excerpt,"createdAt","updatedAt")
SELECT 'batch004-'||b.id,b.id,'en',e.title,b.summary_en,b.essay_en,b.summary_en,now(),now()
FROM editorial_batch_004 b JOIN "Entity" e ON e.id=b.id
ON CONFLICT ("entityId",locale) DO UPDATE SET "shortDescription"=excluded."shortDescription",essay=excluded.essay,excerpt=excluded.excerpt,"updatedAt"=now();

UPDATE "Entity" e SET content=replace(e.content,chr(92)||'n',chr(10)) FROM editorial_batch_004 b WHERE e.id=b.id;
UPDATE "EntityTranslation" t SET essay=replace(t.essay,chr(92)||'n',chr(10)) WHERE t."entityId" IN (SELECT id FROM editorial_batch_004) AND t.locale IN ('es','en');

-- An essay may reference related entities, never the entity currently being viewed.
UPDATE "Entity" e SET content=regexp_replace(e.content, '\[\['||e.slug||'\|(.+?)\]\]', '\1', 'g')
FROM editorial_batch_004 b WHERE e.id=b.id;
UPDATE "EntityTranslation" t SET essay=regexp_replace(t.essay, '\[\['||e.slug||'\|(.+?)\]\]', '\1', 'g')
FROM editorial_batch_004 b JOIN "Entity" e ON e.id=b.id
WHERE t."entityId"=b.id AND t.locale IN ('es','en');

COMMIT;
